let transactions=[],activeFilter="all";const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s),esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));const statusClass=s=>s==="متأخرة"?"late":s==="مكتملة"||s==="مغلقة"?"done":"progress",priorityClass=p=>({"منخفضة":"low","عادية":"normal","مهمة":"important","عاجلة":"urgent","حرجة":"critical"}[p]||"normal");
function toast(m,e=false){const x=$("#toast");x.textContent=m;x.style.background=e?"#8e2f2f":"#163d31";x.classList.add("show");setTimeout(()=>x.classList.remove("show"),3000)}
async function request(path,options={}){const method=options.method||"GET",start=performance.now();console.groupCollapsed(`[مراسلات API] ${method} ${path}`);console.log("الطلب",options.body||"بدون بيانات");try{const res=await fetch(path,{headers:options.body instanceof FormData?{}:{"content-type":"application/json"},...options}),data=(res.headers.get("content-type")||"").includes("json")?await res.json():await res.text();console.log("الاستجابة",{status:res.status,duration_ms:Math.round(performance.now()-start),data});console.groupEnd();if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);return data}catch(e){console.error("فشل الطلب",e);console.groupEnd();toast(e.message,true);throw e}}
const sla=t=>["مكتملة","مغلقة"].includes(t.status)?"مكتملة":Math.ceil((new Date(t.due_at)-new Date())/86400000)<0?`متأخرة ${Math.abs(Math.ceil((new Date(t.due_at)-new Date())/86400000))} يوم`:`متبقي ${Math.ceil((new Date(t.due_at)-new Date())/86400000)} يوم`;
const isLateIncoming=t=>t.type==="وارد"&&!["مكتملة","مغلقة","ملغاة"].includes(t.status)&&new Date(t.due_at)<new Date(),delayDays=t=>Math.max(1,Math.ceil((new Date()-new Date(t.due_at))/86400000));
const row=t=>`<tr class="${isLateIncoming(t)?"late-incoming":""}"><td class="trx-id">${t.reference}</td><td>${t.type}</td><td><strong>${t.subject}</strong>${isLateIncoming(t)?`<small class="late-info">متأخر ${delayDays(t)} يوم · المسؤول: ${t.responsible_name||t.department}</small>`:""}</td><td>${t.entity}</td><td><span class="priority ${priorityClass(t.priority)}">${t.priority}</span></td><td>${t.department}</td><td><span class="badge ${statusClass(isLateIncoming(t)?"متأخرة":t.status)}">${isLateIncoming(t)?"متأخرة":t.status}</span></td><td>${sla(t)}</td><td>${isLateIncoming(t)?`<button class="remind-btn" data-remind="${t.id}">إشعار</button>`:`<button class="row-btn" data-id="${t.id}">←</button>`}</td></tr>`;
function render(list=transactions){$("#allRows").innerHTML=list.map(row).join("")||'<tr><td colspan="9">لا توجد نتائج مطابقة</td></tr>';$("#urgentRows").innerHTML=list.filter(t=>!["مكتملة","مغلقة"].includes(t.status)).slice(0,4).map(t=>`<tr class="${isLateIncoming(t)?"late-incoming":""}"><td class="trx-id">${t.reference}</td><td><strong>${t.subject}</strong><small>${t.entity}</small>${isLateIncoming(t)?`<small class="late-info">المسؤول: ${t.responsible_name||t.department}</small>`:""}</td><td>${t.department}</td><td>${new Date(t.created_at).toLocaleDateString("ar-SA")}</td><td><span class="badge ${statusClass(isLateIncoming(t)?"متأخرة":t.status)}">${isLateIncoming(t)?"متأخرة":t.status}</span></td><td>${isLateIncoming(t)?`متأخرة ${delayDays(t)} يوم`:sla(t)}</td><td>${isLateIncoming(t)?`<button class="remind-btn" data-remind="${t.id}">إرسال إشعار</button>`:`<button class="row-btn" data-id="${t.id}">←</button>`}</td></tr>`).join("");$$(".row-btn").forEach(b=>b.onclick=()=>openDrawer(+b.dataset.id));$$(`[data-remind]`).forEach(b=>b.onclick=()=>sendReminder(+b.dataset.remind))}
async function sendReminder(id){const t=transactions.find(x=>x.id===id),body=prompt("نص المعالجة المطلوب إرساله:",`يرجى معالجة الخطاب ${t?.reference||""} المتأخر والرد عليه`);if(!body)return;const r=await request(`/api/transactions/${id}/remind`,{method:"POST",body:JSON.stringify({body})});toast(`تم إرسال الإشعار إلى ${r.recipients} مستلم`);await loadNotifications()}
async function loadTransactions(params=""){const r=await request("/api/transactions"+params);transactions=r.data;render()}
async function loadMailboxes(){const [incoming,outgoing]=await Promise.all([request("/api/transactions?type=وارد"),request("/api/transactions?type=صادر")]);$("#inboxRows").innerHTML=(incoming.data||[]).map(t=>`<tr><td class="trx-id">${t.reference}</td><td>${t.entity}</td><td>${t.channel||"—"}</td><td>${new Date(t.created_at).toLocaleDateString("ar-SA")}</td><td><span class="badge ${t.status==="قيد الإجراء"?"progress":"done"}">${t.status}</span></td><td>${t.archived_at?"مؤرشفة":t.status}</td><td><button class="row-btn" data-id="${t.id}">←</button></td></tr>`).join("")||'<tr><td colspan="7">لا توجد معاملات واردة</td></tr>';$("#outboxRows").innerHTML=(outgoing.data||[]).map(t=>`<tr><td class="trx-id">${t.reference}</td><td>${t.subject}</td><td>${t.entity}</td><td>${t.delivery_receipt||"غير مسجل"}</td><td>${t.approved_at?new Date(t.approved_at).toLocaleDateString("ar-SA"):"غير معتمد"}</td><td>${t.archived_at?"مؤرشفة":t.status}</td><td><button class="row-btn" data-id="${t.id}">←</button></td></tr>`).join("")||'<tr><td colspan="7">لا توجد معاملات صادرة</td></tr>';$$("#inboxRows .row-btn,#outboxRows .row-btn").forEach(b=>b.onclick=()=>openDrawer(+b.dataset.id))}
async function loadDashboard(){const m=await request("/api/metrics"),v=$$(".kpis article strong"),s=m.summary||{},slaData=m.sla||{};if(v[0])v[0].textContent=s.incoming||0;if(v[1])v[1].textContent=s.outgoing||0;if(v[2])v[2].textContent=s.late||0;if(v[3])v[3].innerHTML=`${slaData.avg_completion_days||0} <b>يوم</b>`;const months=new Intl.DateTimeFormat("ar-SA",{month:"short"}),monthly=m.monthly||[],max=Math.max(1,...monthly.flatMap(x=>[x.incoming||0,x.outgoing||0]));$("#chart").innerHTML=monthly.length?monthly.map(x=>`<div class="bar-group"><div class="bar in" title="وارد: ${x.incoming||0}" style="height:${Math.max(5,(x.incoming||0)/max*100)}px"></div><div class="bar out" title="صادر: ${x.outgoing||0}" style="height:${Math.max(5,(x.outgoing||0)/max*100)}px"></div><small>${months.format(new Date(`${x.month}-01T00:00:00`))}</small></div>`).join(""):'<p>لا توجد حركة مسجلة بعد.</p>';const departments=(m.departments||[]).slice(0,6);$("#progressList").innerHTML=departments.length?departments.map(d=>{const n=d.total?Math.round((d.completed||0)/d.total*100):0;return `<div class="progress-item"><div class="progress-title"><span>${d.department}</span><b>${n}%</b></div><div class="track"><div class="fill ${n>85?"good":""}" style="width:${n}%"></div></div><small>${d.completed||0} من ${d.total||0} مكتملة · ${d.late||0} متأخرة</small></div>`}).join(""):'<p>لا توجد بيانات وحدات بعد.</p>';const w=$(".welcome p");if(w)w.innerHTML=`إجمالي المعاملات <strong>${s.total||0}</strong>، ومنها <strong>${s.late||0}</strong> متأخرة تحتاج المتابعة. نسبة الالتزام بالـSLA: <strong>${slaData.compliance||0}%</strong>.`}
async function loadNotifications(){const r=await request("/api/notifications"),items=r.data||[],unread=items.filter(x=>!x.read_at).length;$("#notificationCount").textContent=unread;$("#notificationCount").hidden=!unread;$("#notificationList").innerHTML=items.length?items.map(n=>`<article class="notification-card ${n.read_at?"":"unread"}" data-notification-transaction="${n.transaction_id||""}"><h3>${n.title}</h3><div class="notification-grid"><span><b>الخطاب:</b> ${n.reference||"—"}</span><span><b>الحالة:</b> ${n.status||"—"}</span><span><b>الموضوع:</b> ${n.subject||"—"}</span><span><b>الجهة المرسلة:</b> ${n.entity||"—"}</span><span><b>التاريخ:</b> ${new Date(n.created_at).toLocaleString("ar-SA")}</span><span><b>المسؤول:</b> ${n.responsible_name||"—"}</span>${n.delay_days?`<span class="late-info"><b>مدة التأخير:</b> ${n.delay_days} يوم</span>`:""}</div><p class="treatment"><b>نص المعالجة:</b> ${n.body}</p></article>`).join(""):'<div class="notification-empty">لا توجد إشعارات حاليًا</div>';$$(`[data-notification-transaction]`).forEach(x=>x.onclick=()=>{const id=+x.dataset.notificationTransaction;if(id){closeNotifications();openDrawer(id)}})}
