function processingStepsView(t){if(t.type!=="وارد")return"";const steps=t.processing_steps||[];return `<section class="processing-section"><div class="processing-head"><div><h3>خطوات معالجة الخطاب</h3><small>${steps.length} خطوة مسجلة</small></div><button class="primary" id="addProcessingStep">＋ تسجيل خطوة</button></div><div class="processing-list">${steps.length?steps.map(s=>`<article class="processing-step"><span class="step-number">${s.step_order}</span><div><h4>${s.action_text}</h4>${s.result_text?`<p><b>النتيجة:</b> ${s.result_text}</p>`:""}<small>${s.performed_by_name} · ${new Date(s.performed_at).toLocaleString("ar-SA")}${s.duration_minutes?` · ${s.duration_minutes} دقيقة`:""}</small></div><span class="step-status">${s.status}</span></article>`).join(""):'<p class="empty-steps">لم تُسجل خطوات معالجة بعد.</p>'}</div></section>`}
async function addProcessingStep(id){const action_text=prompt("ما الخطوة التي قمت بها للرد على الخطاب؟");if(!action_text)return;const result_text=prompt("ما نتيجة هذه الخطوة؟ (اختياري)","")||"";const status=prompt("حالة الخطوة: مكتملة، قيد التنفيذ، أو بانتظار رد","مكتملة")||"مكتملة";const duration_minutes=prompt("المدة المستغرقة بالدقائق (اختياري)","")||null;await request(`/api/transactions/${id}/steps`,{method:"POST",body:JSON.stringify({action_text,result_text,status,duration_minutes})});toast("تم تسجيل خطوة المعالجة");await openDrawer(id)}
async function openDrawer(id){const{data:t}=await request(`/api/transactions/${id}`);$("#drawerTitle").textContent=`${t.reference} — ${t.subject}`;$("#drawerBody").innerHTML=`<div class="detail-meta"><div class="meta-box"><small>الجهة</small><strong>${t.entity}</strong></div><div class="meta-box"><small>الأولوية</small><span class="priority ${priorityClass(t.priority)}">${t.priority}</span></div><div class="meta-box"><small>الإدارة الحالية</small><strong>${t.department}</strong></div><div class="meta-box"><small>الحالة</small><select id="detailStatus"><option>جديدة</option><option>قيد الإجراء</option><option>بانتظار الرد</option><option>متأخرة</option><option>مكتملة</option><option>مغلقة</option></select></div>${t.identity_number?`<div class="meta-box"><small>رقم الهوية</small><strong>${t.identity_number}</strong></div>`:""}</div>${t.message_text?`<h3>نص الرسالة أو المعاملة</h3><div class="message-text">${esc(t.message_text)}</div>`:""}${t.delay_reason?`<div class="delay-note"><strong>سبب التعطيل:</strong> ${t.delay_reason}</div>`:""}${processingStepsView(t)}<h3>خريطة التتبع</h3><div class="timeline">${t.events.map((e,i)=>`<div class="event ${i===t.events.length-1?"current":""}"><h4>${e.action}</h4><p>${e.details}</p><time>${new Date(e.created_at).toLocaleString("ar-SA")}</time></div>`).join("")||"<p>لم تسجل أحداث بعد.</p>"}</div><h3>الملاحظات</h3><div>${t.comments.map(c=>`<p class="meta-box"><strong>${c.body}</strong><small>${c.author}</small></p>`).join("")||"<p>لا توجد ملاحظات.</p>"}</div><div class="modal-actions"><button class="primary" id="transferAction">تحويل المعاملة</button><button class="outline" id="archiveAction">أرشفة</button><button class="outline" id="commentAction">إضافة ملاحظة</button><label class="outline">رفع مرفق<input hidden type="file" id="attachAction"></label></div>`;if($("#archiveAction")){if(t.archived_at)$("#archiveAction").remove();else $("#archiveAction").onclick=async()=>{if(!confirm("نقل المعاملة إلى الأرشيف؟"))return;await request("/api/transactions/"+id+"/archive",{method:"POST"});toast("تمت أرشفة المعاملة");closeDrawer();await loadTransactions()}};if($("#addProcessingStep"))$("#addProcessingStep").onclick=()=>addProcessingStep(id);$("#detailStatus").value=t.status;$("#detailStatus").onchange=async e=>{await request(`/api/transactions/${id}`,{method:"PATCH",body:JSON.stringify({status:e.target.value})});toast("تم تحديث الحالة");await loadTransactions();openDrawer(id)};$("#transferAction").onclick=async()=>{const department=prompt("الإدارة المحال إليها:",t.department);if(!department)return;await request(`/api/transactions/${id}/transfer`,{method:"POST",body:JSON.stringify({department,note:prompt("ملاحظة التحويل:",""),sla_days:3})});toast("تم تحويل المعاملة");await loadTransactions();openDrawer(id)};$("#commentAction").onclick=async()=>{const body=prompt("اكتب الملاحظة:");if(body){await request(`/api/transactions/${id}/comments`,{method:"POST",body:JSON.stringify({body})});toast("تمت إضافة الملاحظة");openDrawer(id)}};$("#attachAction").onchange=async e=>{if(!e.target.files[0])return;const f=new FormData();f.append("file",e.target.files[0]);await request(`/api/transactions/${id}/attachments`,{method:"POST",body:f});toast("تم رفع المرفق");openDrawer(id)};$("#drawer").classList.add("open");$("#backdrop").classList.add("open")}
function closeDrawer(){$("#drawer").classList.remove("open");$("#backdrop").classList.remove("open")}const views=$$(".view");function showView(id){views.forEach(v=>v.classList.toggle("active",v.id===id));$$(".nav-item").forEach(n=>n.classList.toggle("active",n.dataset.view===id));const n=document.querySelector(`[data-view="${id}"]`);$("#pageTitle").textContent=n?n.textContent.replace(/[0-9⌂⇄↓↑▥▤⚙]/g,"").trim():id;$(".sidebar").classList.remove("open");location.hash=id}
