const newType=$("#newType"),identityField=$("#identityField"),identityNumber=$("#identityNumber");function toggleIdentity(){identityField.hidden=newType.value!=="وارد";$("#deliveryReceiptField").hidden=$("#approvedAtField").hidden=newType.value!=="صادر";if(identityField.hidden)identityNumber.value=""}newType.onchange=toggleIdentity;toggleIdentity();identityNumber.oninput=()=>identityNumber.value=identityNumber.value.replace(/\D/g,"").slice(0,10);$("#saveNew").onclick=async e=>{e.preventDefault();const form=$("#newDialog form");if(!form.reportValidity())return;await request("/api/transactions",{method:"POST",body:JSON.stringify({type:newType.value,priority:$("#newPriority").value,identity_number:identityNumber.value||null,subject:$("#subjectInput").value,message_text:$("#messageTextInput").value,confidentiality:$("#newConfidentiality").value,channel:$("#newChannel").value,linked_transaction_id:$("#linkedTransaction").value||null,copy_departments:$("#copyDepartments").value||null,delivery_receipt:$("#deliveryReceipt").value||null,approved_at:$("#approvedAt").value||null,entity:$("#entityInput").value,department:$("#departmentInput").value,sla_days:+$("#slaInput").value})});$("#newDialog").close();form.reset();toggleIdentity();toast("تم تسجيل المعاملة فعليًا");await loadTransactions();showView("transactions")};
$("#filterBtn").onclick=()=>$("#filterPanel").classList.toggle("open");$("#showLate").onclick=()=>{showView("transactions");applyFilters("late")};$$(".tabs button").forEach(b=>b.onclick=()=>{$$(".tabs button").forEach(x=>x.classList.remove("active"));b.classList.add("active");activeFilter=b.dataset.filter;applyFilters()});const searchFields={nameFilter:"name",subjectFilter:"subject",entityFilter:"entity",identityFilter:"identity",referenceFilter:"reference",fromFilter:"from",toFilter:"to"};async function applyFilters(force){const p=new URLSearchParams(),k=force||activeFilter;if(k==="incoming")p.set("type","وارد");if(k==="outgoing")p.set("type","صادر");if(k==="late")p.set("status","متأخرة");if(k==="archive")p.set("archived","1");if($("#deptFilter").value!=="all")p.set("department",$("#deptFilter").value);if($("#statusFilter").value!=="all")p.set("status",$("#statusFilter").value);if($("#priorityFilter").value!=="all")p.set("priority",$("#priorityFilter").value);Object.entries(searchFields).forEach(([id,key])=>{const value=$("#"+id).value.trim();if(value)p.set(key,value)});await loadTransactions("?"+p)}["#deptFilter","#statusFilter","#priorityFilter"].forEach(s=>$(s).onchange=()=>applyFilters());$("#applySearch").onclick=()=>applyFilters();Object.keys(searchFields).forEach(id=>$("#"+id).onkeydown=e=>{if(e.key==="Enter")applyFilters()});$("#identityFilter").oninput=e=>e.target.value=e.target.value.replace(/\D/g,"").slice(0,10);$("#resetFilters").onclick=()=>{$("#deptFilter").value=$("#statusFilter").value=$("#priorityFilter").value="all";Object.keys(searchFields).forEach(id=>$("#"+id).value="");activeFilter="all";loadTransactions()};
